CREATE FUNCTION public.provider_offer_decline_preserved() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.status IN ('declined','expired','withdrawn','canceled','cancelled') THEN PERFORM set_config('app.fleet_decline_only','true',true);ELSE PERFORM set_config('app.fleet_decline_only','false',true);END IF;RETURN NEW;END $$;
CREATE TRIGGER a_provider_offer_decline_preserved BEFORE INSERT OR UPDATE ON public.provider_trip_offers FOR EACH ROW EXECUTE FUNCTION public.provider_offer_decline_preserved();
CREATE OR REPLACE FUNCTION public.provider_fleet_opportunity_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ws uuid;cap text;BEGIN
IF TG_TABLE_NAME='provider_trip_offers' THEN IF NEW.status IN ('declined','expired','withdrawn','canceled','cancelled') THEN RETURN NEW;END IF;ws:=NEW.provider_workspace_id;SELECT capability INTO cap FROM public.trip_distributions WHERE id=NEW.distribution_id;
ELSIF TG_TABLE_NAME='trip_distributions' THEN IF TG_OP='UPDATE' AND NEW.selected_workspace_id IS NOT DISTINCT FROM OLD.selected_workspace_id THEN RETURN NEW;END IF;ws:=NEW.selected_workspace_id;cap:=NEW.capability;
ELSE IF TG_OP='UPDATE' AND NEW.assigned_to IS NOT DISTINCT FROM OLD.assigned_to AND NEW.driver_id IS NOT DISTINCT FROM OLD.driver_id AND NEW.vehicle_id IS NOT DISTINCT FROM OLD.vehicle_id AND NEW.network_provider_workspace_id IS NOT DISTINCT FROM OLD.network_provider_workspace_id THEN RETURN NEW;END IF;IF NEW.trip_kind IS DISTINCT FROM 'passenger' THEN RETURN NEW;END IF;cap:=NEW.transport_type;ws:=coalesce(NEW.contractor_assigned_workspace_id,NEW.network_provider_workspace_id);
IF ws IS NULL AND NEW.assigned_to IS NOT NULL THEN SELECT m.workspace_id INTO ws FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id WHERE m.user_id=NEW.assigned_to AND m.role='owner' AND m.removed_at IS NULL AND w.account_type='provider' ORDER BY w.created_at LIMIT 1;END IF;
IF ws IS NULL AND (NEW.driver_id IS NOT NULL OR NEW.vehicle_id IS NOT NULL) THEN SELECT workspace_id INTO ws FROM public.ride_requests WHERE id=NEW.ride_request_id;END IF;
IF ws IS NULL AND NEW.driver_id IS NOT NULL THEN RAISE EXCEPTION 'Assigned provider workspace required';END IF;
IF NEW.driver_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.drivers WHERE id=NEW.driver_id AND workspace_id=ws AND status='active' AND cap=ANY(service_capabilities) AND (license_expiry IS NULL OR license_expiry>=NEW.pickup_date)) THEN RAISE EXCEPTION 'Active eligible driver in the assigned provider workspace required';END IF;
IF NEW.vehicle_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.vehicles WHERE id=NEW.vehicle_id AND workspace_id=ws AND status='active' AND cap=ANY(service_capabilities)) THEN RAISE EXCEPTION 'Active eligible vehicle in the assigned provider workspace required';END IF;END IF;
IF ws IS NOT NULL AND NOT public.provider_active_fleet(ws,cap) THEN RAISE EXCEPTION 'Add an active eligible driver and vehicle before offering or accepting transportation work';END IF;RETURN NEW;END $$;
CREATE OR REPLACE FUNCTION public.vehicle_private_profile_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF TG_OP='UPDATE' AND (NEW.vin IS DISTINCT FROM OLD.vin OR NEW.insurance_credential_id IS DISTINCT FROM OLD.insurance_credential_id) AND NOT public.business_record_access(OLD.workspace_id,'vehicles',OLD.id,'manage') THEN RAISE EXCEPTION 'Authorized private vehicle editing required';END IF;
IF NEW.vin IS NOT NULL AND NEW.vin<>'' AND NEW.vin !~ '^[A-HJ-NPR-Z0-9]{17}$' THEN RAISE EXCEPTION 'VIN must contain 17 valid letters and digits';END IF;
IF NEW.insurance_credential_id IS NOT NULL AND (TG_OP='INSERT' OR NEW.insurance_credential_id IS DISTINCT FROM OLD.insurance_credential_id OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id) AND NOT EXISTS(SELECT 1 FROM public.provider_credentials c WHERE c.id=NEW.insurance_credential_id AND c.workspace_id=NEW.workspace_id AND c.kind='auto_insurance' AND c.provider_user_id=auth.uid()) THEN RAISE EXCEPTION 'Choose vehicle insurance evidence owned by this workspace and account';END IF;RETURN NEW;END $$;